import{_ as r,o as e,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"外观","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/appearance.md","filePath":"zh-CN/user-guide/settings/appearance.md","lastUpdated":1785993908000}'),o={name:"zh-CN/user-guide/settings/appearance.md"};function n(i,t,l,g,p,d){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h1><p>固定在侧边栏底部、<a href="./about.html">关于</a> 的上方。分两组:<strong>主题模式</strong>和主题选择器本身。</p><h2 id="主题模式" tabindex="-1">主题模式 <a class="header-anchor" href="#主题模式" aria-label="Permalink to &quot;主题模式&quot;">​</a></h2><p>三张卡片，点击即可切换:</p><ul><li><strong>浅色</strong> —— 固定使用单一主题，下方网格只筛选浅色风格的主题。</li><li><strong>深色</strong> —— 同上，只筛选深色风格的主题。</li><li><strong>跟随系统</strong>(浅深分屏预览)—— Lertaro 会在你分别指定的两个主题之间切换——一个用于 Windows 处于浅色模式时，一个用于深色模式时——而不是固定用一个主题，并且 Windows 自己的设置一变化就立刻生效(不需要重启)。</li></ul><p>在<strong>浅色</strong>和<strong>深色</strong>之间切换时，会自动跳到该风格下你上一次选过的主题(跟&quot;跟随系统&quot;用来记住浅/深两侧选择的是同一份记忆)，所以来回切换不会丢失任一侧已经选好的主题。</p><h2 id="界面主题" tabindex="-1">界面主题 <a class="header-anchor" href="#界面主题" aria-label="Permalink to &quot;界面主题&quot;">​</a></h2><p>选中上方的<strong>浅色</strong>或<strong>深色</strong>时，下面是一个只列出对应风格主题的卡片网格。选中<strong>跟随系统</strong> 时，网格会拆成两组:<strong>浅色主题</strong>和<strong>深色主题</strong>——两者默认取符合对应风格、且恰好排在最前面的那个已安装主题，具体有哪些主题完全取决于安装了哪些主题插件。</p><p>每个主题都以卡片形式展示，而不只是一个名字:卡片里是一个用该主题配色渲染的快速搜索窗口缩略图(搜索框加几行搜索结果，其中一行显示为选中态)，切换前就能看到主题的实际观感。当前生效的主题卡片上会有一个勾选徽标。</p><p>内置与随包主题插件:</p><ul><li><strong>CoreExtensions</strong>(内置)—— 浅色、深色、北欧蓝、樱花粉、赛博朋克。</li><li><strong>AnimeThemes</strong>(随包提供，需已安装并启用)—— 新世纪、樱花盛开、天气之子。</li><li><strong>臻选主题 Curated Themes</strong>(随包提供，需已安装并启用)—— 十组浅色/深色成对主题:冰川蓝、陶土棕、森林绿、紫水晶、绯红、石墨灰、靛蓝夜、薄荷青、香槟金、琥珀金。</li></ul><p>其他主题插件也可以用同样的方式往网格里再加卡片。</p>',12)])])}const c=r(o,[["render",n]]);export{h as __pageData,c as default};
